# Homebrew formula for canfit, kept in the canfit repository itself (a tap that is not named
# homebrew-*, so it is tapped with its URL):
#
#   brew tap federicolaterra/canfit https://github.com/federicolaterra/canfit
#   brew install federicolaterra/canfit/canfit
#
# Generated by packaging/render.sh from packaging/templates/canfit.rb and packaging/release.env.
# Do not edit Formula/canfit.rb by hand: edit the template, then run packaging/render.sh.
class Canfit < Formula
  desc "Top command for people running local LLMs and apps"
  homepage "https://github.com/federicolaterra/canfit"
  # No `version`: Homebrew reads it from the URLs' v1.0.0 path segment.
  license "MIT"

  # The release's own archives: one self-contained binary each (static musl on Linux).
  on_macos do
    on_arm do
      url "https://github.com/federicolaterra/canfit/releases/download/v1.0.0/canfit-aarch64-apple-darwin.tar.xz"
      sha256 "819d3795d6b638ce43040ad8fe5ea6a4a091970b8aab883a61298bdb4749e96d"
    end
    on_intel do
      url "https://github.com/federicolaterra/canfit/releases/download/v1.0.0/canfit-x86_64-apple-darwin.tar.xz"
      sha256 "089c96e8c73f709e026205783594f072de85163aa1ec8e953ba45f76f12c6c9d"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/federicolaterra/canfit/releases/download/v1.0.0/canfit-aarch64-unknown-linux-musl.tar.xz"
      sha256 "c19cd4229744f0dbdc2d39c84634cabbbbeb3484e430c7f059b991a42fd8c710"
    end
    on_intel do
      url "https://github.com/federicolaterra/canfit/releases/download/v1.0.0/canfit-x86_64-unknown-linux-musl.tar.xz"
      sha256 "36a789dff2ec33a76f3a0a20280c04e0e4dc1977ac41257d8e9b1c57a5c607f7"
    end
  end

  def install
    bin.install "canfit"
    doc.install "THIRD_PARTY_NOTICES.md"
  end

  test do
    assert_match "canfit #{version}", shell_output("#{bin}/canfit --version")
    assert_match "canfit.snapshot", shell_output("#{bin}/canfit --json")
  end
end
